nginx_config:
daemon off;
master_process on;
worker_processes 4;
pid /tmp/aegisx-bench-kuej1ug5/nginx.pid;
error_log /tmp/aegisx-bench-kuej1ug5/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log /tmp/aegisx-bench-kuej1ug5/access.log combined buffer=64k flush=1s;
    client_body_temp_path /tmp/aegisx-bench-kuej1ug5/body;
    proxy_temp_path /tmp/aegisx-bench-kuej1ug5/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 127.0.0.1:39199; keepalive 256; }
    server {
        listen 127.0.0.1:45513 reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 127.0.0.1:39199;
            proxy_request_buffering off;
            proxy_buffering off;
            proxy_pass http://origin;
        }
    }
}
